import{bV as d,aL as r,u as o,G as a}from"./chunks/framework.DT-LCgF3.js";const g=JSON.parse('{"title":"RAG 完整链路与架构选型（1）写在前面","description":"","frontmatter":{"date":"2026-11-25T14:00:00.000Z","title":"RAG 完整链路与架构选型（1）写在前面","permalink":"/pages/rag01","categories":["AI","RAG"]},"headers":[],"relativePath":"AI/02.RAG/完整链路与架构选型/01.写在前面.md","filePath":"AI/02.RAG/完整链路与架构选型/01.写在前面.md","lastUpdated":1795655557000}'),e={name:"AI/02.RAG/完整链路与架构选型/01.写在前面.md"};function n(s,t,l,h,i,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="rag-完整链路与架构选型-1-写在前面" tabindex="-1">RAG 完整链路与架构选型（1）写在前面 <a class="header-anchor" href="#rag-完整链路与架构选型-1-写在前面" aria-label="Permalink to &quot;RAG 完整链路与架构选型（1）写在前面&quot;">​</a></h1><h2 id="一、写在前面" tabindex="-1">一、写在前面 <a class="header-anchor" href="#一、写在前面" aria-label="Permalink to &quot;一、写在前面&quot;">​</a></h2><h3 id="_1-1-这篇文章解决什么问题" tabindex="-1">1.1 这篇文章解决什么问题 <a class="header-anchor" href="#_1-1-这篇文章解决什么问题" aria-label="Permalink to &quot;1.1 这篇文章解决什么问题&quot;">​</a></h3><p>站内已有 <a href="./../RAG工作机制详解">RAG 工作机制详解</a>，讲清了 RAG 的<strong>概念与五个环节</strong>（分片、索引、召回、重排、生成）。那是一篇&quot;是什么&quot;的文章。</p><p>这一篇是&quot;<strong>怎么搭、怎么选</strong>&quot;。具体回答四类问题：</p><table tabindex="0"><thead><tr><th>问题类型</th><th>本文对应章节</th></tr></thead><tbody><tr><td>每一环具体怎么做，参数怎么调</td><td>第三章、第四章、第五章、第六章</td></tr><tr><td>组件和模型怎么选，为什么这么选</td><td>第七章、第八章</td></tr><tr><td>效果怎么衡量，改完到底有没有变好</td><td>第九章</td></tr><tr><td>什么阶段做什么事，别一上来就过度设计</td><td>第二章、第十章</td></tr></tbody></table><p>本文不重复概念性介绍。如果对&quot;向量&quot;&quot;余弦相似度&quot;&quot;上下文窗口&quot;这些还不熟，建议先读上面那篇。</p><h3 id="_1-2-读者假设" tabindex="-1">1.2 读者假设 <a class="header-anchor" href="#_1-2-读者假设" aria-label="Permalink to &quot;1.2 读者假设&quot;">​</a></h3><ul><li>有后端或全栈开发经验，熟悉 Python（本文示例以 Python 生态为主）或 Golang。</li><li>需要<strong>自己动手搭一套 RAG 系统</strong>并长期维护，而不是只做技术调研。</li><li>关心的是&quot;这套方案在我的数据规模、我的延迟预算下能不能跑起来&quot;，而不是论文指标。</li></ul><p>文中原理性内容与编程语言无关，工程示例以 Python 生态为主，因为当前 RAG 生态的工具链大部分以 Python 为一等公民。</p><h3 id="_1-3-本文的证据标注约定" tabindex="-1">1.3 本文的证据标注约定 <a class="header-anchor" href="#_1-3-本文的证据标注约定" aria-label="Permalink to &quot;1.3 本文的证据标注约定&quot;">​</a></h3><p>这一节请务必先读，它决定了你怎么看待本文的每一句话。</p><p>RAG 是一个<strong>实测数据极度依赖具体语料</strong>的领域。同一个检索策略，在公开榜单上排名靠前，换到你的业务数据上完全可能失效。所以本文严格区分以下几类信息：</p><table tabindex="0"><thead><tr><th>标记</th><th>含义</th><th>你应该怎么看待</th></tr></thead><tbody><tr><td><strong>来源</strong></td><td>附了可点击链接或明确出处的事实：许可协议、模型维度、官方参数默认值、论文自报数据</td><td>可信，但注意来源的时间点</td></tr><tr><td><strong>（常规写法）</strong></td><td>用&quot;通常&quot;&quot;一般&quot;&quot;实践中&quot;等措辞表述的工程经验</td><td>是推断，不是已证实的结论，需在你自己的数据上验证</td></tr><tr><td><strong>（未核实）</strong></td><td>明确标注无法取得可定位来源的内容</td><td>不要直接采信，需自查</td></tr><tr><td>无标注的机理说明</td><td>从已核实原理直接推导的部分</td><td>可作推论依据</td></tr></tbody></table><p>三条必须说明的边界：</p><ol><li><strong>引用来源 ≠ 在你自己的语料上验证过。</strong> 本文引用的榜单类结论都是<strong>跨数据集平均值</strong>。落到具体领域（行业术语密集、专有名词多、长文档多）时，排序可能完全不同。</li><li><strong>凡是标注了&quot;论文自报&quot;的数字，都是论文摘要中的自我报告</strong>，不等于第三方复现结果。</li><li><strong>本文不引用未标注基准日期的榜单分数。</strong> 模型与榜单更新很快，若后续补充榜单数据，必须同时标注数据基准日期；请不要把任何分数当作&quot;当前最新&quot;。</li></ol><p>本文的目标是<strong>给你一套可判断、可验证的决策框架</strong>，而不是给你一堆&quot;照抄就能用&quot;的魔数。凡是没有在你自己数据上验证过的参数，都应视为待调项。</p><h3 id="_1-4-术语表" tabindex="-1">1.4 术语表 <a class="header-anchor" href="#_1-4-术语表" aria-label="Permalink to &quot;1.4 术语表&quot;">​</a></h3><p>全文统一使用以下术语，不再混用近义词：</p><table tabindex="0"><thead><tr><th>术语</th><th>英文 / 缩写</th><th>含义</th></tr></thead><tbody><tr><td>分块</td><td>Chunk</td><td>文档切分后得到的文本片段，是检索的最小单位</td></tr><tr><td>向量化</td><td>Embedding</td><td>把文本映射为定长稠密向量的过程</td></tr><tr><td>双塔</td><td>Bi-Encoder</td><td>查询与文档<strong>各自独立编码</strong>的检索模型结构</td></tr><tr><td>交叉编码器</td><td>Cross-Encoder</td><td>查询与文档<strong>拼接后共同编码</strong>的重排模型结构</td></tr><tr><td>迟交互</td><td>Late Interaction</td><td>保留 token 级向量、在打分时做细粒度对齐的结构（代表：ColBERT）</td></tr><tr><td>近似最近邻</td><td>ANN</td><td>Approximate Nearest Neighbor，用精度换速度的向量检索</td></tr><tr><td>召回</td><td>Recall / Retrieval</td><td>从全库中捞出一批候选，追求&quot;不漏&quot;</td></tr><tr><td>重排</td><td>Rerank</td><td>对召回候选重新精排，追求&quot;排得准&quot;</td></tr><tr><td>级联各级候选数</td><td>K1 / K2 / K3</td><td>分别表示召回候选数、重排后候选数、最终送入生成模型的片段数</td></tr><tr><td>倒数排名融合</td><td>RRF</td><td>Reciprocal Rank Fusion，按排名而非分数融合多路召回结果</td></tr><tr><td>假想文档嵌入</td><td>HyDE</td><td>先让模型生成假想答案，再用它去检索</td></tr><tr><td>套娃表示学习</td><td>MRL</td><td>Matryoshka Representation Learning，支持输出可变维度向量</td></tr></tbody></table><hr>',21)])])}const p=d(e,[["render",n]]);export{g as __pageData,p as default};
